import subprocessimport sysimport time#------------------------------------#scripts = [           "hnnumber9_1[ENC].py",    "rsayel_otp.py"]#------------------------------------#MAX_FAILS = 10processes = []fail_counts = [0] * len(scripts)disabled = [False] * len(scripts)def start(script):    print(f"Starting {script} ...")    return subprocess.Popen([sys.executable, script])for script in scripts:    processes.append(start(script))while True:    for i, p in enumerate(processes):        if disabled[i]:            continue        if p.poll() is not None:            # Process exited            if p.returncode == 0:                # Clean exit - treat as a crash-restart cycle still,                # remove this check if a 0 exit should NOT count as a failure                fail_counts[i] += 1            else:                fail_counts[i] += 1            if fail_counts[i] >= MAX_FAILS:                disabled[i] = True                print(f"{scripts[i]} failed {fail_counts[i]} times in a row. "                      f"Giving up — will NOT restart.")            else:                print(f"{scripts[i]} crashed (fail {fail_counts[i]}/{MAX_FAILS}). Restarting...")                processes[i] = start(scripts[i])    if all(disabled):        print("All scripts have been disabled after repeated failures. Exiting supervisor.")        break    time.sleep(5)